import{_ as d,o,c as t,a1 as c}from"./chunks/framework.BKrM4vFX.js";const p=JSON.parse('{"title":"vtb-mock — ВТБ SMB E-commerce API","description":"vtb-mock — ВТБ SMB E-commerce API. © 2026 ООО «Аксиома» ИНН:7842223709 · mock-services · Apache-2.0 SPDX-License-Identifier: Apache-2.0 Четвёртый внешний банк-адаптер Stage 2 (issue #87). Реализован по официальной документации SMB E-commerce API и callbac","frontmatter":{"sourcePath":"services/vtb-mock/README.md"},"headers":[{"level":1,"title":"vtb-mock — ВТБ SMB E-commerce API","slug":"vtb-mock-ВТБ-smb-e-commerce-api","link":"#vtb-mock-ВТБ-smb-e-commerce-api","children":[{"level":2,"title":"Быстрый старт","slug":"Быстрый-старт","link":"#Быстрый-старт","children":[]},{"level":2,"title":"Поддерживаемый SMB-поток","slug":"Поддерживаемый-smb-поток","link":"#Поддерживаемый-smb-поток","children":[]},{"level":2,"title":"OAuth и заголовки","slug":"oauth-и-заголовки","link":"#oauth-и-заголовки","children":[]},{"level":2,"title":"Суммы, статусы и идемпотентность","slug":"Суммы-статусы-и-идемпотентность","link":"#Суммы-статусы-и-идемпотентность","children":[]},{"level":2,"title":"Callback SMB","slug":"callback-smb","link":"#callback-smb","children":[]},{"level":2,"title":"Ошибки и протокольные оговорки","slug":"Ошибки-и-протокольные-оговорки","link":"#Ошибки-и-протокольные-оговорки","children":[]},{"level":2,"title":"Сценарии, часы и диагностика","slug":"Сценарии-часы-и-диагностика","link":"#Сценарии-часы-и-диагностика","children":[]},{"level":2,"title":"Переменные окружения","slug":"Переменные-окружения","link":"#Переменные-окружения","children":[]},{"level":2,"title":"Протокольные файлы и тесты","slug":"Протокольные-файлы-и-тесты","link":"#Протокольные-файлы-и-тесты","children":[]},{"level":2,"title":"Байтовые квоты состояния (PD-02)","slug":"Байтовые-квоты-состояния-pd-02","link":"#Байтовые-квоты-состояния-pd-02","children":[]}]}],"relativePath":"services/vtb-mock/README.md","filePath":"services/vtb-mock/README.md"}'),a={name:"services/vtb-mock/README.md"};function r(s,e,i,l,n,_){return o(),t("div",null,[...e[0]||(e[0]=[c(`<p>© 2026 ООО «Аксиома» ИНН:7842223709 · mock-services · Apache-2.0 SPDX-License-Identifier: Apache-2.0</p><h1 id="vtb-mock-ВТБ-smb-e-commerce-api" tabindex="-1">vtb-mock — ВТБ SMB E-commerce API <a class="header-anchor" href="#vtb-mock-ВТБ-smb-e-commerce-api" aria-label="Permalink to &quot;vtb-mock — ВТБ SMB E-commerce API&quot;">​</a></h1><nav class="doc-static-toc" aria-label="Оглавление"><p class="doc-static-toc__title">Оглавление</p><ul><li class="doc-static-toc__item doc-static-toc__item--1"><a class="doc-static-toc__link" href="#vtb-mock-ВТБ-smb-e-commerce-api">vtb-mock — ВТБ SMB E-commerce API</a></li><li class="doc-static-toc__item doc-static-toc__item--2"><a class="doc-static-toc__link" href="#Быстрый-старт">Быстрый старт</a></li><li class="doc-static-toc__item doc-static-toc__item--2"><a class="doc-static-toc__link" href="#Поддерживаемый-smb-поток">Поддерживаемый SMB-поток</a></li><li class="doc-static-toc__item doc-static-toc__item--2"><a class="doc-static-toc__link" href="#oauth-и-заголовки">OAuth и заголовки</a></li><li class="doc-static-toc__item doc-static-toc__item--2"><a class="doc-static-toc__link" href="#Суммы-статусы-и-идемпотентность">Суммы, статусы и идемпотентность</a></li><li class="doc-static-toc__item doc-static-toc__item--2"><a class="doc-static-toc__link" href="#callback-smb">Callback SMB</a></li><li class="doc-static-toc__item doc-static-toc__item--2"><a class="doc-static-toc__link" href="#Ошибки-и-протокольные-оговорки">Ошибки и протокольные оговорки</a></li><li class="doc-static-toc__item doc-static-toc__item--2"><a class="doc-static-toc__link" href="#Сценарии-часы-и-диагностика">Сценарии, часы и диагностика</a></li><li class="doc-static-toc__item doc-static-toc__item--2"><a class="doc-static-toc__link" href="#Переменные-окружения">Переменные окружения</a></li><li class="doc-static-toc__item doc-static-toc__item--2"><a class="doc-static-toc__link" href="#Протокольные-файлы-и-тесты">Протокольные файлы и тесты</a></li><li class="doc-static-toc__item doc-static-toc__item--2"><a class="doc-static-toc__link" href="#Байтовые-квоты-состояния-pd-02">Байтовые квоты состояния (PD-02)</a></li></ul></nav><p>Четвёртый внешний банк-адаптер Stage 2 (issue #87). Реализован по официальной документации SMB E-commerce API и callback/тестирования ВТБ. Это SMB API интернет-эквайринга, <strong>не legacy RBS</strong> (<code>vtb.rbsuat.com</code>, <code>*.do</code>): JSON REST base <code>/openapi/smb/efcp/e-commerce/v1/</code>, OAuth 2.0 <code>client_credentials</code> (POST <code>/passport/oauth2/token</code>) → <code>Authorization: Bearer</code> + <code>X-IBM-Client-Id</code> (client_id в нижнем регистре, без <code>@ext.vtb.ru</code>), суммы — десятичные рубли <code>{value, code: &quot;RUB&quot;}</code>.</p><h2 id="Быстрый-старт" tabindex="-1">Быстрый старт <a class="header-anchor" href="#Быстрый-старт" aria-label="Permalink to &quot;Быстрый старт&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> start:vtb</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">          # http://localhost:3106</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># или общий локальный стенд:</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compose</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> up</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -d</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> vtb-mock</span></span></code></pre></div><p>Node ≥ 18, zero npm dependencies. Синтетические дефолты — <code>vtbmocktest</code> / <code>mockpass123</code>; это не тестовые креды банка. Фактические env значения при запуске скрыты в логах. Банк выдаёт реальные тестовые <code>client_id</code>/<code>client_secret</code> подключённому merchant отдельно; не помещайте их в код, тесты, fixtures или общий compose-файл.</p><h2 id="Поддерживаемый-smb-поток" tabindex="-1">Поддерживаемый SMB-поток <a class="header-anchor" href="#Поддерживаемый-smb-поток" aria-label="Permalink to &quot;Поддерживаемый SMB-поток&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Маршрут</th><th>Назначение</th></tr></thead><tbody><tr><td><code>POST /passport/oauth2/token</code></td><td>OAuth 2.0 client_credentials → <code>{access_token, token_type, expires_in}</code> (≈170 с; обновление по <code>expires_in</code>)</td></tr><tr><td><code>POST /openapi/smb/efcp/e-commerce/v1/orders</code></td><td>создать ордер (уникальный merchant <code>orderId</code>, <code>orderName</code>, <code>amount</code> в десятичных рублях) → <code>payUrl</code>; повтор <code>orderId</code> идемпотентен (<code>X-Mock-Replayed</code>)</td></tr><tr><td><code>GET /openapi/smb/efcp/e-commerce/v1/orders/{orderId}</code></td><td>ордер + транзакции платежей/возвратов; <code>status.value</code> на своём уровне</td></tr><tr><td><code>POST /openapi/smb/efcp/e-commerce/v1/orders/preauth</code></td><td>ордер с предавторизацией (<code>twoStageParams</code> обязателен); доступность — <code>MOCK_VTB_PREAUTH</code> («отдельное разрешение банка»)</td></tr><tr><td><code>POST /openapi/smb/efcp/e-commerce/v1/orders/complete/{orderId}</code></td><td>завершить холд суммой ≤ авторизации (частичное подтверждение поддержано)</td></tr><tr><td><code>POST /openapi/smb/efcp/e-commerce/v1/orders/{orderId}/cancel</code></td><td>отмена неоплаченного ордера/preauth до complete, опциональный <code>cancelReason</code></td></tr><tr><td><code>POST /openapi/smb/efcp/e-commerce/v1/refunds</code></td><td>полный/частичный возврат (<code>refundId</code>, <code>paymentId</code>, <code>amount</code>); <code>refundId</code> уникален — повтор это ошибка, не replay</td></tr><tr><td><code>GET /openapi/smb/efcp/e-commerce/v1/refunds/{refundId}</code></td><td>статус возврата</td></tr><tr><td><code>GET /pay/{orderId}</code>, <code>POST /pay/{orderId}/pay</code></td><td>тестовая hosted-страница оплаты (payUrl) с синтетическими [FORK]-картами</td></tr><tr><td><code>GET /health</code>, <code>GET /openapi.json</code></td><td>healthcheck и OpenAPI 3.1</td></tr><tr><td><code>GET /admin</code>, <code>GET /admin/journal</code>, <code>POST /admin/action</code></td><td>консоль ордеров/возвратов/очереди callback и журнала; действия защищены same-origin + CSRF</td></tr><tr><td><code>/mock/time</code>, <code>/mock/scenarios</code>, <code>/mock/state</code>, <code>/mock/reset</code></td><td>виртуальные часы, хаос/сценарии и состояние песочницы</td></tr><tr><td><code>/sandboxes*</code>, <code>/mock/sandboxes</code></td><td>RFC-001 sandbox/control-plane API</td></tr></tbody></table><p>Legacy RBS (<code>vtb.rbsuat.com</code>, <code>/payment/rest/</code>, <code>register.do</code>/<code>paymentorder.do</code>, <code>userName/password</code>, form-urlencoded) <strong>не реализуется и не является альтернативной базой</strong> для <code>/openapi/smb/…</code>. СБП-QR стенды (<code>qr-efcp.bankingapi.ru</code>) и ветка <code>sbpParams</code> — вне области.</p><h2 id="oauth-и-заголовки" tabindex="-1">OAuth и заголовки <a class="header-anchor" href="#oauth-и-заголовки" aria-label="Permalink to &quot;OAuth и заголовки&quot;">​</a></h2><p>Токен выдаётся form-urlencoded <code>POST /passport/oauth2/token</code> (<code>grant_type=client_credentials</code>); ошибки token endpoint — RFC 6749 §5.2 (<code>invalid_client</code>, <code>unsupported_grant_type</code>). TTL токена (дефолт 170 с) живёт на виртуальных часах: <code>POST /mock/time {&quot;advance&quot;:&quot;+171s&quot;}</code> истекает токен, клиент запрашивает новый по <code>expires_in</code>. Бизнес-запросы несут <code>Authorization: Bearer &lt;token&gt;</code> и <code>X-IBM-Client-Id</code> — строго client_id в нижнем регистре без <code>@ext.vtb.ru</code> (суффикс/регистр → <code>invalid_client</code>). <code>Merchant-Authorization</code> опционален (одна политика: для одного ресурса не обязателен).</p><h2 id="Суммы-статусы-и-идемпотентность" tabindex="-1">Суммы, статусы и идемпотентность <a class="header-anchor" href="#Суммы-статусы-и-идемпотентность" aria-label="Permalink to &quot;Суммы, статусы и идемпотентность&quot;">​</a></h2><p><code>amount.value</code> — <strong>десятичные рубли</strong> (<code>10.56</code>), не копейки: принимается число или цифровая строка максимум с двумя знаками после точки, <code>code</code> строго <code>RUB</code>. Статусы живут строго на своём уровне <code>status.value</code>: ордер <code>CREATED/PAID/REFUNDED/PARTIALLY_REFUNDED/CANCELED</code>, операция (платёж/возврат) <code>NEW/CONFIRMED/RECONCILED</code> — не смешивать. Ордер по умолчанию живёт 20 минут (<code>expire</code> возвращается с timezone и миллисекундами; своё — при создании); по истечении незакрытый ордер переходит в <code>CANCELED</code> ([VERIFY]: явного статуса истечения в срезе нет). Повтор <code>orderId</code> в <code>POST /orders</code> идемпотентен и возвращает существующий ордер; повторный <code>refundId</code> — provider-shaped ошибка <code>duplicate_refund_id</code> (409) с DX-подсказкой.</p><h2 id="callback-smb" tabindex="-1">Callback SMB <a class="header-anchor" href="#callback-smb" aria-label="Permalink to &quot;Callback SMB&quot;">​</a></h2><p>Исходящее уведомление — HTTP <code>POST</code> JSON <code>{&quot;type&quot;:&quot;PAYMENT|REFUND&quot;,&quot;object&quot;:{…}}</code> на <code>MOCK_VTB_CALLBACK_URL</code> (один URL на ресурс). <strong>Payload сохраняется и доставляется как есть:</strong> в карточном примере платежа поле статуса — <code>Status</code> (заглавная), в примере возврата — <code>status</code> (строчные); мок не нормализует регистр ключа. Сценарий <code>status-lowercase</code> отдаёт СБП-вариант <code>status</code> у платежа (для проверки парсеров), <code>reconciled</code> — <code>RECONCILED</code> вместо <code>CONFIRMED</code>.</p><p><strong>Подписи, обязательного ACK-кода и расписания ретраев в публичных SMB-доках нет — мок их не выдумывает и не переносит legacy-правила RBS.</strong> Локально доставкой считается любой HTTP 2xx ([FORK] — договорённость стенда, не утверждение протокола); график повторов задаётся <code>MOCK_VTB_CALLBACK_RETRY_MS</code> × <code>MOCK_VTB_CALLBACK_MAX_ATTEMPTS</code> (дефолт 3 × 60 с). Уведомление — не источник истины: после callback выполняйте <code>GET /orders/{orderId}</code> либо <code>GET /refunds/{refundId}</code>. В отсутствии callback URL очередь не создаётся.</p><h2 id="Ошибки-и-протокольные-оговорки" tabindex="-1">Ошибки и протокольные оговорки <a class="header-anchor" href="#Ошибки-и-протокольные-оговорки" aria-label="Permalink to &quot;Ошибки и протокольные оговорки&quot;">​</a></h2><p>Бизнес-ошибки — HTTP 400/401/404/409/429 + тело <code>{error, error_description, field, hint, doc}</code>; коды <code>invalid_request</code>, <code>invalid_token</code>, <code>invalid_client</code>, <code>invalid_amount</code>, <code>order_not_found</code>, <code>payment_not_found</code>, <code>refund_not_found</code>, <code>duplicate_refund_id</code>, <code>amount_exceeds_limit</code>, <code>invalid_order_state</code>, <code>preauth_disabled</code> и др. Публичный SMB-срез фиксирует HTTP-статусы и примеры, но <strong>не полную схему тела бизнес-ошибок</strong> — envelope и словарь кодов это явный <strong>[FORK]</strong> мока (по образцу errorCode-форка Сбера), а не production-каталог ВТБ. Точно так же [FORK]/[VERIFY] являются: синтетические карты взамен истёкшей официальной (<code>4111 1111 1111 1111</code>, 12/24), форма <code>twoStageParams</code>/<code>paymentData</code>/<code>paymentCode</code>, объект <code>{&quot;value&quot;: …}</code> внутри callback-статуса, mock-поле <code>returnUrl</code>, пометка <code>voided</code> у снятого холда (статуса reversal в словаре операций нет).</p><h2 id="Сценарии-часы-и-диагностика" tabindex="-1">Сценарии, часы и диагностика <a class="header-anchor" href="#Сценарии-часы-и-диагностика" aria-label="Permalink to &quot;Сценарии, часы и диагностика&quot;">​</a></h2><p><code>X-Mock-Scenario</code>/<code>/mock/scenarios</code> поддерживают <code>fail</code>, <code>hang</code>, <code>latency</code>, <code>http-500</code>, <code>http-504</code>, <code>webhook-drop</code>/<code>no-callback</code>, <code>webhook-duplicate</code>/<code>callback-duplicate</code>, <code>status-lowercase</code>, <code>reconciled</code>. <code>POST /mock/time</code> принимает <code>{&quot;advance&quot;:&quot;+20m&quot;}</code> (истечение ордера), <code>{&quot;advance&quot;:&quot;+171s&quot;}</code> (истечение токена) и <code>{&quot;advance&quot;:&quot;+60s&quot;}</code> (retry callback). Сценарии, история, токены, журнал и состояние изолируются по <code>X-Mock-Sandbox</code>. Журнал redacts чувствительные поля; PAN не пишется в журнал и не сохраняется в ордере — только маска <code>first6**last4</code>. В hosted-режиме SSRF-проверка исходящих callback включена по умолчанию; <code>SSRF_BLOCKED</code> — терминальный отказ без повторов.</p><h2 id="Переменные-окружения" tabindex="-1">Переменные окружения <a class="header-anchor" href="#Переменные-окружения" aria-label="Permalink to &quot;Переменные окружения&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Переменная</th><th>Default</th><th>Назначение</th></tr></thead><tbody><tr><td><code>MOCK_HOST</code> / <code>MOCK_PORT</code></td><td><code>0.0.0.0</code> / <code>3106</code></td><td>адрес и порт HTTP-сервера</td></tr><tr><td><code>MOCK_VTB_CLIENT_ID</code></td><td><code>vtbmocktest</code></td><td>синтетический client_id (в <code>X-IBM-Client-Id</code> — lowercase, без <code>@ext.vtb.ru</code>)</td></tr><tr><td><code>MOCK_VTB_CLIENT_SECRET</code></td><td><code>mockpass123</code></td><td>синтетический client_secret</td></tr><tr><td><code>MOCK_VTB_TOKEN_TTL_SECS</code></td><td><code>170</code></td><td>срок access_token в секундах; поддерживает длительность (<code>2m</code>); TTL живёт на виртуальных часах</td></tr><tr><td><code>MOCK_VTB_PUBLIC_BASE_URL</code></td><td><code>http://localhost:\${MOCK_VTB_HOST_PORT:-3106}</code></td><td>внешний base URL, используемый в <code>payUrl</code></td></tr><tr><td><code>MOCK_VTB_CALLBACK_URL</code></td><td>пусто</td><td>callback URL ресурса (один на ресурс); без него очередь не создаётся</td></tr><tr><td><code>MOCK_VTB_CALLBACK_RETRY_MS</code></td><td><code>60000</code> (<code>60s</code>)</td><td>интервал retry; число в миллисекундах либо длительность (<code>60s</code>, <code>1m</code>)</td></tr><tr><td><code>MOCK_VTB_CALLBACK_MAX_ATTEMPTS</code></td><td><code>3</code></td><td>максимум доставок; значение меньше 1 нормализуется в 1</td></tr><tr><td><code>MOCK_VTB_ORDER_TTL_SECS</code></td><td><code>1200</code></td><td>срок нового ордера (20 минут); поле <code>expire</code> запроса переопределяет его для конкретного ордера</td></tr><tr><td><code>MOCK_VTB_PREAUTH</code></td><td><code>true</code></td><td>разрешить <code>POST /orders/preauth</code> в локальном стенде (upstream — отдельное разрешение банка)</td></tr><tr><td><code>MOCK_STATE_FILE</code></td><td>пусто</td><td>сохранение доменного состояния/очереди между рестартами</td></tr><tr><td><code>MOCK_SANDBOX_FILE</code></td><td><code>&lt;MOCK_STATE_FILE&gt;.sandboxes.json</code></td><td>база RFC-001 реестра песочниц</td></tr><tr><td><code>MOCK_SANDBOX_SWEEP_MS</code></td><td><code>60000</code></td><td>интервал sweep TTL/retention, когда worker включён</td></tr><tr><td><code>MOCK_BLOCK_PRIVATE_WEBHOOKS</code></td><td><code>false</code> (hosted → <code>true</code>)</td><td>запрет исходящих callback в private/reserved адреса; SSRF-отказ терминален</td></tr><tr><td><code>MOCK_VIRTUAL_CLOCK</code></td><td>текущее время</td><td>начальное значение виртуальных часов</td></tr><tr><td><code>MOCK_ADMIN_TOKEN</code> / <code>MOCK_OPERATOR_TOKEN</code></td><td>пусто</td><td>защита управляющих <code>/admin*</code> и <code>/mock/*</code></td></tr><tr><td><code>MOCK_HOSTED</code></td><td><code>false</code></td><td><code>true</code> включает hosted fail-closed для управляющих поверхностей и default SSRF-защиту</td></tr><tr><td><code>MOCK_TENANCY</code></td><td>авто</td><td>sandbox-модель RFC-001 (<code>off</code>, <code>namespaces</code>, <code>owned</code>)</td></tr><tr><td><code>MOCK_SANDBOX_TOKEN</code></td><td>пусто</td><td>owner-token default sandbox в <code>owned</code>-модели; при <code>MOCK_HOSTED=1</code> без него <code>default</code> не обслуживается (MS-12)</td></tr><tr><td><code>MOCK_SANDBOX_TTL_MS</code> / <code>MOCK_SANDBOX_MAX</code></td><td><code>owned: 24h</code> / <code>owned: 100</code></td><td>аренда и число песочниц</td></tr><tr><td><code>MOCK_SANDBOX_MAX_DOCUMENTS</code></td><td><code>owned: 5000</code></td><td>квота ордеров + возвратов + callback-документов на sandbox</td></tr><tr><td><code>MOCK_SANDBOX_RETENTION_MS</code></td><td><code>0</code></td><td>retention терминальных callback-записей; ордеры не удаляются</td></tr><tr><td><code>MOCK_SANDBOX_HOST_SUFFIX</code></td><td>пусто</td><td>опциональный hostname-формат sandbox URL</td></tr><tr><td><code>MOCK_SANDBOX_CREATE_LIMIT</code></td><td><code>owned: 20</code></td><td>rate-limit создания sandbox на IP</td></tr></tbody></table><h2 id="Протокольные-файлы-и-тесты" tabindex="-1">Протокольные файлы и тесты <a class="header-anchor" href="#Протокольные-файлы-и-тесты" aria-label="Permalink to &quot;Протокольные файлы и тесты&quot;">​</a></h2><ul><li>Манифест drift-проверки: <a href="https://github.com/rucorp/mock-services/blob/main/protocols/vtb-smb.json" target="_blank" rel="noreferrer"><code>protocols/vtb-smb.json</code></a>.</li><li>OpenAPI: <a href="https://github.com/rucorp/mock-services/blob/main/docs/openapi/vtb-mock.openapi.json" target="_blank" rel="noreferrer"><code>docs/openapi/vtb-mock.openapi.json</code></a>, также <code>GET /openapi.json</code>.</li><li>Selftest (OAuth/TTL, orders/refunds/preauth, Status-status callback, SSRF, RFC-001): <code>npm run test:vtb</code>.</li><li>Ограничения безопасности общие с проектом: <a href="./../../SECURITY"><code>SECURITY.md</code></a>.</li></ul><h2 id="Байтовые-квоты-состояния-pd-02" tabindex="-1">Байтовые квоты состояния (PD-02) <a class="header-anchor" href="#Байтовые-квоты-состояния-pd-02" aria-label="Permalink to &quot;Байтовые квоты состояния (PD-02)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Env</th><th>Дефолт</th><th>Назначение</th></tr></thead><tbody><tr><td><code>MOCK_SANDBOX_MAX_STATE_BYTES</code></td><td>пусто: <code>8388608</code> (8 МиБ) при <code>maxDocuments &gt; 0</code>, иначе без лимита</td><td>байты JSON одной песочницы; <code>0</code> выключает</td></tr><tr><td><code>MOCK_SANDBOX_GLOBAL_MAX_STATE_BYTES</code></td><td><code>67108864</code> (64 МиБ)</td><td>сумма байт JSON всех песочниц рантайма, включая <code>default</code>; <code>0</code> выключает</td></tr></tbody></table><p>Значения задаются в целых байтах. Пусто сохраняет дефолты. Квота per-sandbox не ограничивает память контейнера; общий бюджет меньше <code>mem_limit: 128m</code>, но не равен RSS. Превышение глобального бюджета на записи или байтовых квот при импорте <code>/mock/state</code> → HTTP 400, <code>errorCode: 400</code>, <code>kind: &#39;bytes&#39;</code>, <code>code: sandbox_state_budget_exceeded</code> / <code>sandbox_state_quota_exceeded</code>, с откатом отклонённого состояния. Правила/история/журнал остаются volatile. Подробности и границы — <a href="./../../packages/core/README#байтовые-квоты-песочниц-pd-02-74">документация ядра</a>.</p>`,28)])])}const h=d(a,[["render",r]]);export{p as __pageData,h as default};
